head.script:
scwin.screenId = "jldfil45300";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert('채권상장 ID 변경은 채권상장신청 사이트를 이용하시기 바랍니다.');
    await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/main.do). 전환 대상 화면이 확정되면 연결됩니다.');
    /* sdd-asis-lifecycle:end */
};


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil45300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_usrId_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_usrId_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_usrId_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.chkDuplicateReset();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45300.ipt_usrId_onchange' }); }
};

/**
 * @event
 * @name scwin.img_46_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_46_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_46_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.chkDuplicate()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45300.img_46_onclick' }); }
};

/**
 * @event
 * @name scwin.img_51_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_51_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_51_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.changeUsrId()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45300.img_51_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ChkDuplicate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ChkDuplicate = async function () {
    const sbmOptions = {
        id: "tx_fn_ChkDuplicate",
        method: "post",
        action: "/outer/popRegister.do?method=searchIdDuplication",
        ref: "dma_ChkDuplicateReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil45300.tx_fn_ChkDuplicate" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_ChangeUsrId_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ChangeUsrId_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_ChangeUsrId_xhr", unresolved: "action:self_submit:tx_fn_ChangeUsrId_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.chkDuplicate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkDuplicate = async function () {
    /* sdd-asis-lifecycle:begin fn_ChkDuplicate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('personalForm');
    const usrIdObj = $c.util.getComponent('ipt_usrId');
    if (await scwin.nullChk(usrIdObj)) {
        return;
    }
    if (!await scwin.chkNoneNum(usrIdObj)) {
        return;
    }
    if (!await scwin.chkAlphaNum(usrIdObj, 6, 20)) {
        return;
    }
    frm.action = '/outer/popRegister.do?method=searchIdDuplication';

    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/main/firstLogin.do", unresolved: "nav:" + "/main/firstLogin.do" }; })();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.useUsrId
 * @author Inswave
 * @date 2026. 09. 29
 * @param _usrId
 * @returns
 * @hidden N
*/
scwin.useUsrId = function (_usrId) {
    /* sdd-asis-lifecycle:begin fn_UseUsrId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('personalForm');
    $c.util.getComponent("ipt_usrId").setValue(_usrId);
    $c.util.getComponent('dma_ChkDuplicateReq').set('chkDuplicate', 'Y');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkDuplicateReset
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkDuplicateReset = function () {
    /* sdd-asis-lifecycle:begin fn_ChkDuplicateReset — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('personalForm');
    $c.util.getComponent('dma_ChkDuplicateReq').set('chkDuplicate', 'N');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeUsrId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeUsrId = async function () {
    /* sdd-asis-lifecycle:begin fn_ChangeUsrId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('personalForm');
    if (await scwin.nullChk($c.util.fieldEl('ipt_usrId', 'usrId'))) {
        return;
    }
    if ($c.util.getComponent('dma_ChkDuplicateReq').get('chkDuplicate') !== 'Y') {
        await $c.win.alert('아이디 중복 확인을 하셔야 합니다.');
        return;
    }
    $c.util.getComponent('dma_ChkDuplicateReq').set('method', 'firstLoginChangeUsrId');
    frm.action = '/main/firstLogin.do';
    const result = scwin.trim(await scwin.tx_fn_ChangeUsrId_xhr());
    if (result !== 'success') {
        await $c.win.alert('아이디 변경 중 에러가 발생 하였습니다.\n잠시 후 다시 이용하여 주시기 바랍니다.');
    } else {
        await $c.win.alert('아이디를 변경하였습니다.\n변경 아이디로 다시 로그인 하여 주시기 바랍니다.');
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil45000/jldfil45000.xml');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.nullChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.nullChk = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_NullChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    // ie11에서 alt값을 'undefined'로 인식하므로 수정
    if(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === ''  || typeof ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === 'undefined') {
        return await scwin.isNull(_obj, _obj.title);
    }

    return await scwin.isNull(_obj, ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkNoneNum
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.chkNoneNum = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_ChkNoneNum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    const numChk = /^[\d]{1,}$/;
    if(numChk.test(_obj.value)){
        await $c.win.alert("'" + ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) + "' 항목은 숫자만으로 구성할 수 없습니다.");	
        _obj.value = '';
        _obj.focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkAlphaNum
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _sNum _eNum
 * @returns
 * @hidden N
*/
scwin.chkAlphaNum = async function (_obj, _sNum, _eNum) {
    /* sdd-asis-lifecycle:begin fn_ChkAlphaNum — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    const strChk = eval("/^[a-zA-Z0-9]{" + _sNum + "," + _eNum + "}$/");
    if(!strChk.test(_obj.value)){
        await $c.win.alert("'" + ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) + "' 항목은 영문과 숫자의 조합으로 " + _sNum + "~" + _eNum + "자리내에서 입력하세요");	
        _obj.value = '';
        _obj.focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.trim = function (_str) {
    /* sdd-asis-lifecycle:begin fn_Trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _msg
 * @returns
 * @hidden N
*/
scwin.isNull = async function (_obj, _msg) {
    /* sdd-asis-lifecycle:begin fn_IsNull — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    if(scwin.trim(_obj.value) === ''){
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요");
        _obj.focus();
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};
